<script setup lang="ts">
const supabase = useSupabaseClient()
const email = ref(''), password = ref(''), fullName = ref(''), error = ref(''), success = ref(''), busy = ref(false)
async function register() { busy.value = true; error.value = ''; success.value = ''; try { const { error: err } = await supabase.auth.signUp({ email: email.value, password: password.value, options: { data: { full_name: fullName.value } } }); if (err) throw err; success.value = 'Registration received. Check your email for a confirmation link, if email confirmation is enabled.' } catch (e: any) { error.value = e.message || 'Registration failed.' } finally { busy.value = false } }
</script>
<template><div class="mx-auto max-w-md px-5 py-16"><form class="panel space-y-5" @submit.prevent="register"><h1 class="text-3xl font-bold">Create account</h1><label class="block">Full name<input v-model="fullName" class="input mt-2" required autocomplete="name" /></label><label class="block">Email<input v-model="email" type="email" class="input mt-2" required autocomplete="email" /></label><label class="block">Password<input v-model="password" type="password" minlength="8" class="input mt-2" required autocomplete="new-password" /></label><p v-if="error" role="alert" class="text-red-300">{{ error }}</p><p v-if="success" role="status" class="text-teal-300">{{ success }}</p><button class="btn w-full" :disabled="busy">{{ busy ? 'Creating…' : 'Register' }}</button><NuxtLink to="/auth/login" class="block text-center text-sm text-teal-300">Already have an account?</NuxtLink></form></div></template>
